toolScript:
// Core Logic
        const input = document.getElementById('raw-input');
        const output = document.getElementById('bionic-output');
        const slider = document.getElementById('fixation-slider');
        const sideEff = document.getElementById('side-efficiency');
        const placeholder = document.getElementById('output-placeholder');
        // Gamification State
        const GameState = {
            totalWords: parseInt(localStorage.getItem('bionic_total_words')) || 0,
            streak: parseInt(localStorage.getItem('bionic_streak')) || 0,
            lastVisit: localStorage.getItem('bionic_last_visit'),
            level: 1,
            nextLevelXP: 1000,
            init() {
                // Check Streak
                const today = new Date().toDateString();
                if (this.lastVisit !== today) {
                    const yesterday = new Date();
                    yesterday.setDate(yesterday.getDate() - 1);
                    if (this.lastVisit === yesterday.toDateString()) {
                        this.streak++;
                    } else if (this.lastVisit) {
                        // Streak broken logic could go here, but let's be kind and keep streaks forgiving
                    } else {
                        this.streak = 1;
                    }
                    this.lastVisit = today;
                    localStorage.setItem('bionic_last_visit', today);
                    localStorage.setItem('bionic_streak', this.streak);
                }
                this.updateUI();
            },
            addXP(words) {
                this.totalWords += words;
                localStorage.setItem('bionic_total_words', this.totalWords);
                this.updateUI();
            },
            updateUI() {
                // Calculate Level
                this.level = Math.floor(this.totalWords / 1000) + 1;
                this.nextLevelXP = this.level * 1000;
                // Titles
                const titles = ["Novice", "Reader", "Scanner", "Speedster", "Bionic Eye", "Neuro-Master", "Time Lord"];
                const titleIndex = Math.min(this.level - 1, titles.length - 1);
                document.getElementById('user-level-badge').innerText = this.level;
                document.getElementById('user-rank-title').innerText = titles[titleIndex];
                document.getElementById('stats-words').innerText = this.totalWords.toLocaleString();
                document.getElementById('stats-streak').innerText = this.streak;
                document.getElementById('xp-current').innerText = (this.totalWords % 1000);
                document.getElementById('xp-next').innerText = "1000";
                // Bar width
                const pct = ((this.totalWords % 1000) / 1000) * 100;
                document.getElementById('xp-bar').style.width = `${pct}%`;
            }
        };
        // Tour Guide Logic
        const TourGuide = {
            steps: [
                { el: 'step-1-input', title: 'Paste Content Here', desc: 'Start by pasting any article, email, or document into this raw text buffer.' },
                { el: 'step-2-slider', title: 'Adjust Intensity', desc: 'Slide to control how strong the bolding effect is. Higher levels for skimming, lower for deep reading.' },
                { el: 'step-3-fonts', title: 'Choose Typography', desc: 'Switch between Sans-Serif and Serif fonts to find what fits your eye best.' },
                { el: 'step-4-output', title: 'Bionic Output', desc: 'Your converted text appears here instantly. Read the bolded letters to guide your eyes.' },
                { el: 'step-5-action', title: 'Copy Result', desc: 'One click to copy the formatted text to your clipboard, ready for your docs.' }
            ],
            current: 0,
            active: false,
            init() {
                if (!localStorage.getItem('bionic_tour_done')) {
                    setTimeout(() => this.start(), 1000);
                }
            },
            start() {
                this.active = true;
                this.current = 0;
                document.getElementById('tour-overlay').classList.add('active');
                this.showStep();
            },
            showStep() {
                const step = this.steps[this.current];
                const target = document.getElementById(step.el);
                const tooltip = document.getElementById('tour-tooltip');
                // Cleanup previous highlight
                document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
                // Highlight new
                target.classList.add('tour-highlight');
                target.scrollIntoView({ behavior: 'smooth', block: 'center' });
                // Position Tooltip
                const rect = target.getBoundingClientRect();
                const tooltipRect = tooltip.getBoundingClientRect();
                // Simple positioning logic (centered bottom)
                let top = rect.bottom + 15;
                let left = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
                // Bounds check
                if (left < 10) left = 10;
                tooltip.style.top = `${top + window.scrollY}px`;
                tooltip.style.left = `${left}px`;
                document.getElementById('tour-title').innerText = step.title;
                document.getElementById('tour-desc').innerText = step.desc;
                tooltip.classList.add('active');
            },
            next() {
                this.current++;
                if (this.current >= this.steps.length) {
                    this.end();
                } else {
                    this.showStep();
                }
            },
            end() {
                this.active = false;
                document.getElementById('tour-overlay').classList.remove('active');
                document.getElementById('tour-tooltip').classList.remove('active');
                document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
                localStorage.setItem('bionic_tour_done', 'true');
                showToast("Tutorial Complete! Happy Reading.");
            }
        };
        function createConfetti() {
            for (let i = 0; i < 50; i++) {
                const confetti = document.createElement('div');
                confetti.classList.add('confetti');
                confetti.style.left = Math.random() * 100 + 'vw';
                confetti.style.backgroundColor = ['#EE6C4D', '#2563eb', '#fcd34d'][Math.floor(Math.random() * 3)];
                confetti.style.animationDuration = Math.random() * 3 + 2 + 's';
                document.body.appendChild(confetti);
                setTimeout(() => confetti.remove(), 5000);
            }
        }
        function loadSample() {
            input.value = "Bionic reading is a technique used to speed up the reading process by guiding the eyes through text with artificial fixation points. By highlighting the initial characters of words, the brain can more effectively 'autocomplete' the rest of the word, significantly reducing the cognitive load required to process each sentence. This is particularly effective for those with ADHD or dyslexia, as it provides visual anchors that prevent the eye from skipping lines or losing focus in dense paragraphs.";
            convertText();
        }
        function convertText() {
            const text = input.value.trim();
            const strength = parseInt(slider.value); // 1 to 5
            if (!text) {
                output.innerHTML = '';
                placeholder.style.display = 'flex';
                sideEff.innerText = '0%';
                return;
            }
            placeholder.style.display = 'none';
            // Algorithm Logic: 
            const ratio = 0.1 + (strength * 0.1);
            // Split by words but keep delimiters (spaces, newlines)
            const segments = text.split(/([\s\n\t]+)/);
            const converted = segments.map(segment => {
                // If it's whitespace, return as is
                if (segment.match(/^[\s\n\t]+$/)) return segment;
                return processWord(segment, ratio, strength);
            }).join('');
            output.innerHTML = converted;
            // Stats update
            const totalChars = text.length;
            const efficiency = Math.round((strength / 5) * 85); // Heuristic
            sideEff.innerText = efficiency + '%';
        }
        function processWord(word, ratio, strength) {
            const len = word.length;
            if (len === 0) return word;
            let boldLen = Math.ceil(len * ratio);
            // Constraints for short words
            if (len <= 3) {
                boldLen = 1;
            } else if (strength === 5 && len > 3) {
                boldLen = Math.ceil(len * 0.65);
            }
            const boldPart = word.substring(0, boldLen);
            const normalPart = word.substring(boldLen);
            return `<b>${boldPart}</b>${normalPart}`;
        }
        function setFont(fontName, btn) {
            output.style.fontFamily = fontName;
            document.querySelectorAll('.font-option').forEach(el => el.classList.remove('active'));
            btn.classList.add('active');
        }
        function copyBionic() {
            if (!output.innerText) {
                showToast("Buffer Empty. Input text first.");
                return;
            }
            // Gamification Trigger
            const wordCount = input.value.split(/\s+/).length;
            GameState.addXP(wordCount);
            createConfetti();
            // Rich text copy logic
            const range = document.createRange();
            range.selectNode(output);
            window.getSelection().removeAllRanges();
            window.getSelection().addRange(range);
            document.execCommand('copy');
            window.getSelection().removeAllRanges();
            showToast(`Synced ${wordCount} words to clipboard!`);
        }
        function clearEditor() {
            if (!confirm("Purge current buffer?")) return;
            input.value = '';
            convertText();
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest flex items-center gap-2";
            toast.innerHTML = `<span class="text-emerald-400"></span> ${msg}`;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // --- SCROLL LOGIC ---
        // Listeners
        input.addEventListener('input', convertText);
        slider.addEventListener('input', convertText);
        // Initial Load
        document.addEventListener('DOMContentLoaded', () => {
            loadSample();
            GameState.init();
            TourGuide.init();
        });
